mapper.select:
SELECT r.id, r.requirement_id AS requirementId, req.title AS requirementTitle, r.reviewer_id AS reviewerId, u.real_name AS reviewerName, r.result, r.comment, r.suggestions, r.reviewed_at AS reviewedAt FROM reviews r JOIN requirements req ON req.id = r.requirement_id AND req.deleted_at = 0 LEFT JOIN users u ON r.reviewer_id = u.id WHERE 1 = 1
AND r.requirement_id = #{requirementId}
AND r.result = #{result}
AND (req.title LIKE CONCAT('%', #{keyword}, '%') OR r.comment LIKE CONCAT('%', #{keyword}, '%') OR r.suggestions LIKE CONCAT('%', #{keyword}, '%'))
AND (r.reviewer_id = #{currentUserId} OR req.creator_id = #{currentUserId})
ORDER BY COALESCE(r.reviewed_at, '9999-12-31') DESC, r.id DESC
